



const requestedRoute=new URLSearchParams(location.search).get('route')||document.body.dataset.route;
let current=routes.some(r=>r.id===requestedRoute)?requestedRoute:'yamagata';
const $=id=>document.getElementById(id);
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function imgMarkup(p,small=false){const [id,title,note]=p;const photo=photos[id];if(!photo||!photo.data)return `<figure style="margin:0;padding:50px 24px;background:#e4ebe5;border-radius:7px"><strong>${escapeHTML(title)}</strong><p style="font-size:13px">实拍图源暂未能读取，本卡保留景点介绍。<br>没有用其他地点的照片代替。</p><a href="${photo?.source||'#'}" target="_blank" rel="noopener noreferrer">查看相仓官方图文 ↗</a></figure>`;return `<figure style="margin:0"><button type="button" class="photo-button" data-photo="${id}" data-title="${escapeHTML(title)}" data-note="${escapeHTML(note)}" aria-label="放大照片：${escapeHTML(title)}"><img referrerpolicy="no-referrer" decoding="async" src="${photo.data}" alt="${escapeHTML(title)}" loading="eager"><span class="zoom">放大查看</span></button><figcaption class="photo-caption"><strong>${escapeHTML(title)}</strong> · ${escapeHTML(note)}<br><a href="${photo.source}" target="_blank" rel="noopener noreferrer">${escapeHTML(photo.label)}</a></figcaption></figure>`;}
function albumMarkup(items,label,small=false){return `<div class="album" role="region" aria-roledescription="相册" aria-label="${escapeHTML(label)}"><div class="album-track" tabindex="0" aria-label="${escapeHTML(label)}照片，可用左右方向键切换">${items.map((p,i)=>`<div class="album-slide" role="group" aria-label="第 ${i+1} 张，共 ${items.length} 张">${imgMarkup(p,small||i>0)}</div>`).join('')}</div><div class="album-controls"><button type="button" data-step="-1" aria-label="上一张" disabled>‹</button><div class="album-dots">${items.map((p,i)=>`<button type="button" data-slide="${i}" aria-label="查看第 ${i+1} 张：${escapeHTML(p[1])}" aria-current="${i===0}"></button>`).join('')}</div><span class="album-count" role="status" aria-live="polite">1 / ${items.length}</span><button type="button" data-step="1" aria-label="下一张">›</button></div><p class="album-hint">左右滑动浏览 · 点击照片放大</p></div>`;}
function initAlbums(){document.querySelectorAll('.album').forEach(album=>{const track=album.querySelector('.album-track'),slides=[...track.children],dots=[...album.querySelectorAll('[data-slide]')];let active=0;const update=()=>{active=Math.max(0,Math.min(slides.length-1,Math.round(track.scrollLeft/(track.clientWidth+16))));album.querySelector('.album-count').textContent=`${active+1} / ${slides.length}`;album.querySelector('[data-step="-1"]').disabled=active===0;album.querySelector('[data-step="1"]').disabled=active===slides.length-1;dots.forEach((d,i)=>d.setAttribute('aria-current',String(i===active)));};const go=i=>track.scrollTo({left:Math.max(0,Math.min(slides.length-1,i))*(track.clientWidth+16),behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});album.addEventListener('click',e=>{const b=e.target.closest('[data-step],[data-slide]');if(!b)return;go(b.hasAttribute('data-slide')?Number(b.dataset.slide):active+Number(b.dataset.step));});track.addEventListener('scroll',update,{passive:true});track.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();go(e.key==='Home'?0:e.key==='End'?slides.length-1:active+(e.key==='ArrowRight'?1:-1));});});}
function makeNav(){ $('routeNav').innerHTML=routes.map((r,i)=>`<a href="${r.id}${$('returnDate').value==='2'?'-late':''}.html" id="tab-${r.id}" class="route-choice" role="tab" aria-selected="${r.id===current}" aria-controls="routePanel" data-route="${r.id}"><img referrerpolicy="no-referrer" loading="eager" decoding="async" src="${photos[r.photos[0][0]].data}" alt="${escapeHTML(r.photos[0][1])}"><b><span class="idx">0${i+1}</span>${escapeHTML(r.name)}</b><small>${escapeHTML(r.fit)}</small></a>`).join('');}
function render(){const r=routes.find(x=>x.id===current), late=$('returnDate').value==='2';document.querySelectorAll('[data-route]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.route===current)));$('routePanel').setAttribute('aria-labelledby','tab-'+r.id);$('region').textContent=r.en+' / '+r.name;$('routeTitle').textContent=r.theme;$('summary').textContent=r.summary;$('description').textContent=r.intro;$('routePath').innerHTML=r.path.map(s=>`<span>${escapeHTML(s)}</span>`).join('');$('stay').textContent='住宿节奏 · '+r.stay;
$('photoArea').innerHTML=albumMarkup(r.photos,r.name+'路线总览');
const days=r.days.map((d,i)=>({base:d,detail:r.daily[i]}));if(late)days.push({base:['1/1',...r.extra],detail:r.extraDetail});days.push({base:[late?'1/2':'1/1','返回东京',r.return,late?'东京／按上海航班衔接条件安排':'东京'],detail:r.returnDetail});
$('dayLinks').innerHTML=days.map((x,i)=>`<a href="#day-${r.id}-${i}">${escapeHTML(x.base[0])} · ${i===days.length-1?'返程':'D'+(i+1)}</a>`).join('');
$('itinerary').innerHTML=days.map((x,i)=>{const d=x.base,t=x.detail;return `<article id="day-${r.id}-${i}" class="day ${i===days.length-1?'return':''}"><div class="day-visual">${albumMarkup(t.photos,d[0]+' '+d[1],true)}</div><div class="day-copy"><div class="day-top"><span class="day-number">DAY ${String(i+1).padStart(2,'0')}</span><time>${escapeHTML(d[0])}</time></div><h4>${escapeHTML(d[1])}</h4><ol>${t.stops.map(a=>`<li><span class="period">${escapeHTML(a[0])}</span><div><strong class="stop-name">${escapeHTML(a[1])}</strong><p>${escapeHTML(a[2])}</p></div></li>`).join('')}</ol><div class="day-logistics"><p><b>交通</b> · ${escapeHTML(t.move)}</p><p><b>节奏</b> · ${escapeHTML(t.pace)}</p><div class="sleep">住宿 · ${escapeHTML(d[3])}</div><p class="day-backup"><b>调整条件</b> · ${escapeHTML(t.backup)}</p></div></div></article>`}).join('');
initAlbums();
$('duration').textContent=late?'12/27—1/2 · 含往返移动 7 天':'12/27—1/1 · 含往返移动 6 天';$('returnNote').className='return-note'+(late?' caution':'');$('returnNote').textContent=late?'1/2 回东京为条件方案：若上海返程仍是 1/2，须核实航班时刻、机场及冬季衔接余量；目前不能视作已可衔接。':'当前选择 1/1 回东京：保留 1 晚缓冲，1/2 再从东京飞上海。5 晚在外地，12/27 为抵达日、1/1 为返程日。';
$('transport').textContent=r.transport;$('caveat').textContent=r.caveat;$('events').innerHTML=r.events.map(e=>`<article class="event"><span class="status ${['暂定','待更新','固定年例','往年参考','不在日期内'].includes(e[0])?'pending':''}">${escapeHTML(e[0])}</span><div><h4>${escapeHTML(e[1])}</h4><p>${escapeHTML(e[3])}</p></div><div class="event-date">${escapeHTML(e[2])}<br><a href="${e[4]}" target="_blank" rel="noopener noreferrer">查看来源 ↗</a></div></article>`).join('');$('sources').innerHTML=r.sources.map(s=>`<a href="${s[1]}" target="_blank" rel="noopener noreferrer">${escapeHTML(s[0])} ↗</a>`).join('');}
$('routeNav').addEventListener('click',e=>{const b=e.target.closest('[data-route]');if(b){e.preventDefault();current=b.dataset.route;render();}});$('routeNav').addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();let i=routes.findIndex(r=>r.id===current);i=e.key==='Home'?0:e.key==='End'?routes.length-1:(i+(e.key==='ArrowRight'?1:-1)+routes.length)%routes.length;current=routes[i].id;render();$('tab-'+current).focus();});$('returnDate').addEventListener('change',render);
$('routePanel').addEventListener('click',e=>{const b=e.target.closest('[data-photo]');if(!b)return;const photo=photos[b.dataset.photo];$('lightboxTitle').textContent=b.dataset.title;$('largePhoto').src=photo.data;$('largePhoto').alt=b.dataset.title;$('lightboxCaption').textContent=b.dataset.note;$('photoSource').href=photo.source;if(typeof $('lightbox').showModal==='function')$('lightbox').showModal();else location.href=photo.data;});$('closePhoto').addEventListener('click',()=>$('lightbox').close());$('lightbox').addEventListener('click',e=>{if(e.target===$('lightbox'))$('lightbox').close();});makeNav();render();document.documentElement.classList.add('enhanced');
if(new URLSearchParams(location.search).get('preview')==='mobile')document.body.classList.add('mobile-preview');
